    size_t find_index(const std::vector<double>& grid, double val) const {
        if (grid.size() < 2) return 0;
        if (val <= grid.front()) return 0;
        if (val >= grid.back()) return grid.size() - 2;
        auto it = std::upper_bound(grid.begin(), grid.end(), val);
        return std::distance(grid.begin(), it) - 1;
    }

